package com.aoo.bcg.common.cache;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class CacheShardRouterTest{@Test void spreadsHotEntitiesAndProducesClusterHashTags(){var router=new CacheShardRouter(64);int[]counts=new int[64];for(int i=1;i<=100_000;i++)counts[router.shard("club-member-"+i)]++;int min=java.util.Arrays.stream(counts).min().orElseThrow(),max=java.util.Arrays.stream(counts).max().orElseThrow();assertTrue((double)max/min<1.2);String key=router.key(CacheKey.of("prod","club","member",100,1));assertTrue(key.matches("prod:club:member:\\{club-[0-9]{3}}:100:v1"));assertEquals(router.shard("100"),router.shard("100"));}}
